  @protected
  void sse_encode_runtime_event_payload_dto(
    RuntimeEventPayloadDto self,
    SseSerializer serializer,
  ) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    switch (self) {
      case RuntimeEventPayloadDto_RuntimeStateChanged(
        lifecycle: final lifecycle,
      ):
        sse_encode_i_32(0, serializer);
        sse_encode_runtime_lifecycle_dto(lifecycle, serializer);
      case RuntimeEventPayloadDto_StartupFailed(phase: final phase):
        sse_encode_i_32(1, serializer);
        sse_encode_startup_phase_dto(phase, serializer);
      case RuntimeEventPayloadDto_AppearanceSettingsChanged():
        sse_encode_i_32(2, serializer);
      case RuntimeEventPayloadDto_LibraryRootsChanged():
        sse_encode_i_32(3, serializer);
      case RuntimeEventPayloadDto_LibraryRootChanged(
        libraryRootId: final libraryRootId,
      ):
        sse_encode_i_32(4, serializer);
        sse_encode_String(libraryRootId, serializer);
    }
  }

